Problem Description:
Fix any and all bugs in this code:

// module top_module (
//     input      cpu_overheated,
//     output reg shut_off_computer,
//     input      arrived,
//     input      gas_tank_empty,
//     output reg keep_driving  ); //

//     always @(*) begin
//         if (cpu_overheated)
//            shut_off_computer = 1;
//     end

//     always @(*) begin
//         if (~arrived)
//            keep_driving = ~gas_tank_empty;
//     end

// endmodule

module top_module (
	input cpu_overheated,
	output reg shut_off_computer,
	input arrived,
	input gas_tank_empty,
	output reg keep_driving
);

Erroneous Implementation:

always @(posedge clk) begin
		if (cpu_overheated)
			shut_off_computer <= 1;
		else
			shut_off_computer <= 0;
	end
	always @(posedge clk) begin
		if (!arrived)
			keep_driving <= ~gas_tank_empty;
		else
			keep_driving <= 0;
	end
endmodule

